import json, requests, sys

webhook_url = "https://open.feishu.cn/open-apis/bot/v2/hook/39ace5b8-ddf6-4ccf-8912-2c2681c618a4"

card = {
    "msg_type": "interactive",
    "card": {
        "header": {
            "title": {
                "tag": "plain_text",
                "content": "✅ 澳洲冰箱新品监控日报 - 2026年6月25日"
            },
            "template": "blue"
        },
        "elements": [
            {
                "tag": "div",
                "text": {
                    "tag": "lark_md",
                    "content": "今日 5 品牌均无新品上架或状态变更。\n\n---\n\n**海信 Hisense** (53款产品)\n✅ 无变化 — 最新排序前24款型号与基线一致，2026年5款新品无新增\n\n**美的 Midea** (12款产品)\n✅ 无变化 — MDRT580MTF45AP (413L) 仍为 Coming Soon，无新增型号\n\n**三星 Samsung**\n✅ 无变化 — 搜索未发现新冰箱型号，仅香港能源标签 RB34F7B4D12/SH\n\n**LG**\n✅ 无变化 — 搜索未发现新冰箱型号，仅香港能源标签 M356MPYBQC / M226MPYBAM\n\n**西屋 Westinghouse**\n✅ 无变化 — 精选产品5款不变，WHE6874SA 仍为 DISCONTINUED"
                }
            },
            {
                "tag": "hr"
            },
            {
                "tag": "note",
                "elements": [
                    {
                        "tag": "plain_text",
                        "content": "由 Incaier Agent 自动监控 | 下次汇总：明天下午 3:07"
                    }
                ]
            }
        ]
    }
}

resp = requests.post(webhook_url, json=card, timeout=15)
result = {"status_code": resp.status_code, "body": resp.json()}
with open(sys.argv[-1], "w", encoding="utf-8") as f:
    json.dump(result, f, ensure_ascii=False, indent=2)

